# -*- coding: utf-8 -*-
# Centre de notifications (cloche, demandes de coequipier acceptables en un clic),
# corrections responsive (dropdown reactions, overflow mobile)
# A lancer depuis la racine du dossier pompiers-app : python3 apply_update_13.py
import pathlib

FILES = {}

FILES['backend/prisma/schema.prisma'] = '// Schema Prisma - Application de suivi de camps d\'entrainement\n// Par defaut : SQLite (aucune installation requise).\n// Pour passer sur PostgreSQL en production, remplacer le provider ci-dessous\n// par "postgresql" et adapter DATABASE_URL dans .env\n\ngenerator client {\n  provider = "prisma-client-js"\n}\n\ndatasource db {\n  provider = "sqlite"\n  url      = env("DATABASE_URL")\n}\n\n// Note : pas d\'enum Prisma ici (ExerciseUnit / RecurrenceType) car SQLite ne supporte pas\n// les enums natifs. Les valeurs autorisees ("REPS"/"SECONDS", "DAILY"/"WEEKLY"/"EVERY_N_DAYS")\n// sont validees cote API avec zod.\n\nmodel User {\n  id             String   @id @default(cuid())\n  email          String   @unique\n  passwordHash   String\n  name           String\n  weightKg       Float?\n  heightCm       Float?\n  birthDate      DateTime?\n  sex            String?  // "F" | "M" | "AUTRE" | null, libre / optionnel\n  sport          String?  // pratique principale, libre choix dans une liste cote frontend\n  sportLevel     String?  // "LOISIR" | "COMPETITION" | null\n  avatarBase64   String?  // photo de profil encodee en data URL (redimensionnee cote client)\n  location       String?  // ville/region, libre\n  equipment      String?  // JSON array du materiel disponible (voir src/utils/equipment.ts)\n  createdAt      DateTime @default(now())\n\n  memberships    CampMembership[]\n  createdCamps   Camp[]            @relation("CampCreator")\n  createdExos    Exercise[]        @relation("ExerciseCreator")\n  logs           ExerciseLog[]\n  subscriptions  PushSubscription[]\n  badges         UserBadge[]\n  campMessages   CampMessage[]\n  sentMessages   DirectMessage[]   @relation("MessageSender")\n  receivedMessages DirectMessage[] @relation("MessageRecipient")\n  chronoSessions ChronoSession[]\n  circuitLogs    CampCircuitLog[]\n  restDays       RestDay[]\n  favoriteCircuits FavoriteCircuit[]\n  reactions      Reaction[]\n  resetTokens    PasswordResetToken[]\n  sentConnections     Connection[] @relation("ConnectionRequester")\n  receivedConnections Connection[] @relation("ConnectionRecipient")\n  notifications  Notification[]\n}\n\nmodel Exercise {\n  id          String       @id @default(cuid())\n  name        String\n  description String?\n  unit        String       // "REPS" ou "SECONDS"\n  category    String?      // "UPPER" | "LOWER" | "ABS" | "CARDIO" | "FULL_BODY" | "MOBILITY"\n  equipment   String?      // JSON array du materiel necessaire (voir src/utils/equipment.ts) ; vide/null = aucun materiel\n  imageBase64 String?      // photo/illustration de l\'exercice (redimensionnee cote client)\n  videoUrl    String?      // lien video explicatif (ex: YouTube), optionnel\n  isCustom    Boolean      @default(false)\n  createdById String?\n  createdBy   User?        @relation("ExerciseCreator", fields: [createdById], references: [id])\n  createdAt   DateTime     @default(now())\n\n  campExercises CampExercise[]\n  logs          ExerciseLog[]\n}\n\nmodel Camp {\n  id          String    @id @default(cuid())\n  name        String\n  description String?\n  code        String    @unique\n  createdById String\n  createdBy   User      @relation("CampCreator", fields: [createdById], references: [id])\n  startDate   DateTime?\n  endDate     DateTime?\n  createdAt   DateTime  @default(now())\n\n  exercises CampExercise[]\n  circuits  CampCircuit[]\n  members   CampMembership[]\n  logs      ExerciseLog[]\n  circuitLogs CampCircuitLog[]\n  messages  CampMessage[]\n}\n\n// Consigne d\'un exercice au sein d\'un camp : definie UNIQUEMENT par le createur du camp\n// (la "casquette entraineur"). Tous les membres suivent la meme consigne.\nmodel CampExercise {\n  id             String   @id @default(cuid())\n  campId         String\n  exerciseId     String\n  description    String?  // court descriptif/consigne redige par le createur du camp\n  targetSets     Int      @default(3)\n  targetMode     String   @default("FIXED") // "FIXED" (objectif chiffre) ou "MAX" (a fond, sans cible fixe)\n  targetValue    Int?     // nombre de repetitions OU de secondes vise (voir Exercise.unit) ; inutilise si targetMode = MAX\n  recurrenceType String   @default("DAILY") // "DAILY" | "WEEKLY" | "EVERY_N_DAYS" | "WEEKLY_COUNT"\n  daysOfWeek     String?  // JSON array ex: "[1,3,5]" (0=dimanche ... 6=samedi), utilise si WEEKLY\n  intervalDays   Int?     // utilise si EVERY_N_DAYS\n  timesPerWeek   Int?     // utilise si WEEKLY_COUNT (X fois par semaine, n\'importe quel jour)\n  startDate      DateTime @default(now())\n\n  camp     Camp     @relation(fields: [campId], references: [id], onDelete: Cascade)\n  exercise Exercise @relation(fields: [exerciseId], references: [id])\n  logs     ExerciseLog[]\n\n  @@unique([campId, exerciseId])\n}\n\nmodel CampMembership {\n  id       String   @id @default(cuid())\n  userId   String\n  campId   String\n  role     String   @default("PLAYER") // "COACH" (ne fait pas les exercices) | "PLAYER" (participe)\n  joinedAt DateTime @default(now())\n  user     User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  camp     Camp     @relation(fields: [campId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, campId])\n}\n\nmodel ExerciseLog {\n  id         String   @id @default(cuid())\n  userId     String\n  campId     String\n  exerciseId String\n  date       DateTime // jour concerne (heure normalisee a minuit)\n  setsDone   Int\n  valueDone  Int      // repetitions ou secondes realisees (moyenne/estimation par serie, cf notes)\n  completed  Boolean  @default(true)\n  createdAt  DateTime @default(now())\n\n  user         User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  camp         Camp          @relation(fields: [campId], references: [id], onDelete: Cascade)\n  exercise     Exercise      @relation(fields: [exerciseId], references: [id])\n  campExercise CampExercise? @relation(fields: [campId, exerciseId], references: [campId, exerciseId])\n\n  @@unique([userId, campId, exerciseId, date])\n}\n\nmodel PushSubscription {\n  id        String   @id @default(cuid())\n  userId    String\n  endpoint  String   @unique\n  p256dh    String\n  auth      String\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel UserBadge {\n  id        String   @id @default(cuid())\n  userId    String\n  badgeKey  String   // identifiant du badge, voir src/utils/badges.ts pour le catalogue\n  earnedAt  DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, badgeKey])\n}\n\n// Discussion de groupe entre les membres d\'un camp\nmodel CampMessage {\n  id        String   @id @default(cuid())\n  campId    String\n  userId    String\n  body      String\n  createdAt DateTime @default(now())\n\n  camp Camp @relation(fields: [campId], references: [id], onDelete: Cascade)\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n// Message prive entre deux utilisateurs (reserve aux personnes qui partagent au moins un camp)\nmodel DirectMessage {\n  id          String   @id @default(cuid())\n  senderId    String\n  recipientId String\n  body        String\n  createdAt   DateTime @default(now())\n\n  sender    User @relation("MessageSender", fields: [senderId], references: [id], onDelete: Cascade)\n  recipient User @relation("MessageRecipient", fields: [recipientId], references: [id], onDelete: Cascade)\n}\n\n// Seance de circuit training "libre" (construite depuis l\'onglet Chrono, pas liee a un camp).\n// Enregistree une fois terminee, pour alimenter l\'historique d\'activite de l\'utilisateur.\nmodel ChronoSession {\n  id                   String   @id @default(cuid())\n  userId               String\n  name                 String? // nom optionnel donne par l\'utilisateur\n  items                String  // JSON : liste ordonnee des noms d\'exercices du circuit\n  workSeconds          Int\n  restSeconds          Int\n  rounds               Int\n  roundRestSeconds     Int\n  totalDurationSeconds Int\n  completedAt          DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n// Circuit training defini par le createur d\'un camp (alternative aux exercices individuels).\n// Compose d\'une liste ordonnee d\'exercices avec temps de travail/repos, nombre de tours, etc.\nmodel CampCircuit {\n  id               String   @id @default(cuid())\n  campId           String\n  name             String\n  description      String?\n  items            String   // JSON : [{ "exerciseId": "...", "name": "..." }, ...] ordonne\n  workSeconds      Int\n  restSeconds      Int\n  rounds           Int\n  roundRestSeconds Int\n  recurrenceType   String   @default("DAILY")\n  daysOfWeek       String?\n  intervalDays     Int?\n  timesPerWeek     Int?\n  startDate        DateTime @default(now())\n\n  camp Camp             @relation(fields: [campId], references: [id], onDelete: Cascade)\n  logs CampCircuitLog[]\n}\n\n// Validation, par un membre, d\'un circuit de camp realise un jour donne\nmodel CampCircuitLog {\n  id              String   @id @default(cuid())\n  userId          String\n  campCircuitId   String\n  campId          String\n  date            DateTime\n  durationSeconds Int\n  completed       Boolean  @default(true)\n  createdAt       DateTime @default(now())\n\n  user        User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  campCircuit CampCircuit @relation(fields: [campCircuitId], references: [id], onDelete: Cascade)\n  camp        Camp        @relation(fields: [campId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, campCircuitId, date])\n}\n\n// Jour marque comme "repos justifie" par l\'utilisateur (blessure, voyage...) : ce jour\n// n\'est jamais compte comme un manque dans les calculs de regularite/streak, ni comme du\n// depend  (il est neutre). S\'applique globalement, tous camps/exercices confondus.\nmodel RestDay {\n  id        String   @id @default(cuid())\n  userId    String\n  date      DateTime // jour concerne (heure normalisee a minuit)\n  reason    String?\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, date])\n}\n\n// Circuit training "favori" enregistre par un utilisateur depuis l\'onglet Chrono,\n// pour le relancer directement sans le reconstruire.\nmodel FavoriteCircuit {\n  id               String   @id @default(cuid())\n  userId           String\n  name             String\n  items            String   // JSON : liste ordonnee des noms d\'exercices\n  workSeconds      Int\n  restSeconds      Int\n  rounds           Int\n  roundRestSeconds Int\n  createdAt        DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n// Reaction rapide (encouragement) laissee par un membre de camp sur une seance validee\n// par un autre membre (exercice ou circuit). Purement social, aucun impact sur les stats.\nmodel Reaction {\n  id         String   @id @default(cuid())\n  userId     String   // qui reagit\n  targetType String   // "exercise" ou "circuit" (type de log cible)\n  targetId   String   // id du ExerciseLog ou CampCircuitLog cible\n  type       String   // cle du type de reaction, voir src/utils/reactions.ts\n  createdAt  DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, targetType, targetId, type])\n}\n\n// Jeton de reinitialisation de mot de passe, a duree de vie limitee\nmodel PasswordResetToken {\n  id        String   @id @default(cuid())\n  userId    String\n  token     String   @unique\n  expiresAt DateTime\n  used      Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n// Relation "coequipier" entre deux utilisateurs (demande + acceptation), inspiree d\'une\n// demande d\'ami : donne acces au profil complet (regularite, camps, badges) une fois acceptee.\nmodel Connection {\n  id          String   @id @default(cuid())\n  requesterId String\n  recipientId String\n  status      String   @default("PENDING") // "PENDING" | "ACCEPTED"\n  createdAt   DateTime @default(now())\n\n  requester User @relation("ConnectionRequester", fields: [requesterId], references: [id], onDelete: Cascade)\n  recipient User @relation("ConnectionRecipient", fields: [recipientId], references: [id], onDelete: Cascade)\n\n  @@unique([requesterId, recipientId])\n}\n\n// Notification en-app (centre de notifications) : persiste ce qui a ete pousse en push,\n// pour un historique consultable dans l\'appli meme sans avoir recu le push (ou sans\n// notifications activees sur l\'appareil).\nmodel Notification {\n  id        String   @id @default(cuid())\n  userId    String\n  type      String   // "REACTION" | "CAMP_MESSAGE" | "DIRECT_MESSAGE" | "TEAMMATE_REQUEST" | "CAMP_UPDATED" | "REMINDER"\n  title     String\n  body      String\n  link      String?  // chemin frontend a ouvrir au clic, ex: "/camps/xxx/discussion"\n  relatedId String?  // id de la ressource concernee (ex: connectionId pour TEAMMATE_REQUEST)\n  read      Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n'
FILES['backend/src/services/notifications.ts'] = 'import cron from "node-cron";\nimport webpush from "web-push";\nimport { prisma } from "../lib/prisma";\nimport { isDueOnDate, toDayStart, weekStart } from "../utils/recurrence";\n\n// Configure web-push avec les clés VAPID (à générer avec `npm run vapid:generate`)\nexport function initPush() {\n  const publicKey = process.env.VAPID_PUBLIC_KEY;\n  const privateKey = process.env.VAPID_PRIVATE_KEY;\n  const subject = process.env.VAPID_SUBJECT || "mailto:contact@example.com";\n\n  if (!publicKey || !privateKey) {\n    console.warn(\n      "[push] Clés VAPID manquantes : les notifications push sont désactivées. " +\n        "Génère-les avec `npm run vapid:generate` et renseigne .env"\n    );\n    return;\n  }\n  webpush.setVapidDetails(subject, publicKey, privateKey);\n  console.log("[push] Notifications push configurées.");\n}\n\n// Vérifie, pour chaque utilisateur, les exercices dus aujourd\'hui (selon la consigne du camp)\n// et pas encore faits, puis envoie une notification de rappel groupée.\nexport async function sendDailyReminders() {\n  const today = toDayStart(new Date());\n  const weekStartDate = weekStart(today);\n\n  const memberships = await prisma.campMembership.findMany({\n    include: {\n      user: { include: { subscriptions: true } },\n      camp: { include: { exercises: { include: { exercise: true } } } },\n    },\n  });\n\n  const dueByUser = new Map<string, { name: string }[]>();\n\n  for (const membership of memberships) {\n    const { camp, userId } = membership;\n    if (camp.startDate && today.getTime() < toDayStart(camp.startDate).getTime()) continue;\n    if (camp.endDate && today.getTime() > toDayStart(camp.endDate).getTime()) continue;\n\n    for (const ce of camp.exercises) {\n      if (!isDueOnDate(ce, today)) continue;\n\n      const alreadyLogged = await prisma.exerciseLog.findUnique({\n        where: {\n          userId_campId_exerciseId_date: {\n            userId,\n            campId: ce.campId,\n            exerciseId: ce.exerciseId,\n            date: today,\n          },\n        },\n      });\n      if (alreadyLogged) continue;\n\n      // Pour "X fois par semaine, n\'importe quel jour" : pas de rappel si le quota\n      // hebdomadaire est déjà atteint par un autre jour de la semaine.\n      if (ce.recurrenceType === "WEEKLY_COUNT" && ce.timesPerWeek) {\n        const weekCount = await prisma.exerciseLog.count({\n          where: { userId, campId: ce.campId, exerciseId: ce.exerciseId, date: { gte: weekStartDate, lte: today } },\n        });\n        if (weekCount >= ce.timesPerWeek) continue;\n      }\n\n      const list = dueByUser.get(userId) || [];\n      list.push({ name: ce.exercise.name });\n      dueByUser.set(userId, list);\n    }\n  }\n\n  const subscriptionsByUser = new Map(memberships.map((m) => [m.userId, m.user.subscriptions]));\n\n  for (const [userId, pending] of dueByUser) {\n    if (pending.length === 0) continue;\n    const subscriptions = subscriptionsByUser.get(userId) ?? [];\n    if (subscriptions.length === 0) continue;\n\n    const names = [...new Set(pending.map((p) => p.name))];\n    const title = "C\'est le moment de faire votre séance ! 💪";\n    const bodyText =\n      names.length === 1\n        ? `${names[0]} t\'attend aujourd\'hui.`\n        : `${names.slice(0, 3).join(", ")}${names.length > 3 ? "…" : ""} t\'attendent aujourd\'hui.`;\n\n    await prisma.notification.create({\n      data: { userId, type: "REMINDER", title, body: bodyText, link: "/aujourdhui" },\n    });\n\n    const payload = JSON.stringify({ title, body: bodyText });\n\n    for (const sub of subscriptions) {\n      try {\n        await webpush.sendNotification(\n          { endpoint: sub.endpoint, keys: { p256dh: sub.p256dh, auth: sub.auth } },\n          payload\n        );\n      } catch (err: any) {\n        // Abonnement expiré ou invalide : on le retire\n        if (err.statusCode === 404 || err.statusCode === 410) {\n          await prisma.pushSubscription.delete({ where: { id: sub.id } }).catch(() => {});\n        } else {\n          console.error("[push] Erreur d\'envoi :", err.message);\n        }\n      }\n    }\n  }\n}\n\n// Planifie l\'envoi quotidien à l\'heure configurée (REMINDER_HOUR, défaut 18h, heure serveur)\nexport function scheduleReminders() {\n  const hour = Number(process.env.REMINDER_HOUR ?? 18);\n  const cronExpr = `0 ${hour} * * *`;\n  cron.schedule(cronExpr, () => {\n    sendDailyReminders().catch((err) => console.error("[push] Erreur lors de l\'envoi des rappels :", err));\n  });\n  console.log(`[push] Rappels quotidiens planifiés à ${hour}h (heure serveur).`);\n}\n\n// Envoie une notification à UN utilisateur précis (tous ses appareils abonnés), avec un\n// titre/corps libres. Utilisé pour prévenir d\'un nouveau message (camp ou privé).\nexport async function sendPushToUser(userId: string, title: string, body: string) {\n  const subscriptions = await prisma.pushSubscription.findMany({ where: { userId } });\n  if (subscriptions.length === 0) return;\n\n  const payload = JSON.stringify({ title, body });\n  for (const sub of subscriptions) {\n    try {\n      await webpush.sendNotification({ endpoint: sub.endpoint, keys: { p256dh: sub.p256dh, auth: sub.auth } }, payload);\n    } catch (err: any) {\n      if (err.statusCode === 404 || err.statusCode === 410) {\n        await prisma.pushSubscription.delete({ where: { id: sub.id } }).catch(() => {});\n      } else {\n        console.error("[push] Erreur d\'envoi :", err.message);\n      }\n    }\n  }\n}\n\n// Cree une notification dans le centre de notifications de l\'appli ET envoie le push\n// correspondant. C\'est la fonction a utiliser partout (reactions, messages, demandes de\n// coequipier, modifications de camp, rappels...) plutot que sendPushToUser seul, pour que\n// la personne retrouve l\'info dans l\'appli meme si elle n\'a pas recu/active le push.\nexport async function notifyUser(\n  userId: string,\n  type: string,\n  title: string,\n  body: string,\n  link?: string,\n  relatedId?: string\n) {\n  await prisma.notification.create({\n    data: { userId, type, title, body, link: link ?? null, relatedId: relatedId ?? null },\n  });\n  await sendPushToUser(userId, title, body);\n}\n'
FILES['backend/src/routes/notifications.ts'] = 'import { Router } from "express";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\n\nconst router = Router();\nrouter.use(requireAuth);\n\n// Liste les notifications recentes de l\'utilisateur (les plus recentes en premier)\nrouter.get("/", async (req: AuthRequest, res) => {\n  const notifications = await prisma.notification.findMany({\n    where: { userId: req.userId },\n    orderBy: { createdAt: "desc" },\n    take: 50,\n  });\n  res.json(notifications);\n});\n\nrouter.get("/unread-count", async (req: AuthRequest, res) => {\n  const count = await prisma.notification.count({ where: { userId: req.userId, read: false } });\n  res.json({ count });\n});\n\n// Marque une notification comme lue\nrouter.post("/:id/read", async (req: AuthRequest, res) => {\n  const notif = await prisma.notification.findUnique({ where: { id: req.params.id } });\n  if (!notif || notif.userId !== req.userId) return res.status(404).json({ error: "Notification introuvable." });\n  await prisma.notification.update({ where: { id: req.params.id }, data: { read: true } });\n  res.status(204).send();\n});\n\n// Marque toutes les notifications comme lues\nrouter.post("/read-all", async (req: AuthRequest, res) => {\n  await prisma.notification.updateMany({ where: { userId: req.userId, read: false }, data: { read: true } });\n  res.status(204).send();\n});\n\nexport default router;\n'
FILES['backend/src/index.ts'] = 'import "dotenv/config";\nimport express from "express";\nimport cors from "cors";\n\nimport authRoutes from "./routes/auth";\nimport userRoutes from "./routes/users";\nimport exerciseRoutes from "./routes/exercises";\nimport campRoutes from "./routes/camps";\nimport campExerciseRoutes from "./routes/campExercises";\nimport todayRoutes from "./routes/today";\nimport logRoutes from "./routes/logs";\nimport progressRoutes from "./routes/progress";\nimport pushRoutes from "./routes/push";\nimport badgeRoutes from "./routes/badges";\nimport campMessageRoutes from "./routes/campMessages";\nimport messageRoutes from "./routes/messages";\nimport campCircuitRoutes from "./routes/campCircuits";\nimport chronoSessionRoutes from "./routes/chronoSessions";\nimport activityRoutes from "./routes/activity";\nimport restDayRoutes from "./routes/restDays";\nimport reactionRoutes from "./routes/reactions";\nimport favoriteCircuitRoutes from "./routes/favoriteCircuits";\nimport connectionRoutes from "./routes/connections";\nimport notificationRoutes from "./routes/notifications";\nimport { initPush, scheduleReminders } from "./services/notifications";\n\nconst app = express();\n\napp.use(cors({ origin: process.env.FRONTEND_URL || "*" }));\napp.use(express.json());\n\napp.get("/api/health", (_req, res) => res.json({ status: "ok" }));\n\napp.use("/api/auth", authRoutes);\napp.use("/api/users", userRoutes);\napp.use("/api/exercises", exerciseRoutes);\napp.use("/api/camps", campRoutes);\napp.use("/api/camp-exercises", campExerciseRoutes);\napp.use("/api/today", todayRoutes);\napp.use("/api/logs", logRoutes);\napp.use("/api/progress", progressRoutes);\napp.use("/api/push", pushRoutes);\napp.use("/api/badges", badgeRoutes);\napp.use("/api/camps", campMessageRoutes);\napp.use("/api/messages", messageRoutes);\napp.use("/api/camp-circuits", campCircuitRoutes);\napp.use("/api/chrono-sessions", chronoSessionRoutes);\napp.use("/api/activity", activityRoutes);\napp.use("/api/rest-days", restDayRoutes);\napp.use("/api/reactions", reactionRoutes);\napp.use("/api/favorite-circuits", favoriteCircuitRoutes);\napp.use("/api/connections", connectionRoutes);\napp.use("/api/notifications", notificationRoutes);\n\n// Gestion d\'erreur generique (evite qu\'une exception fasse planter le process)\napp.use((err: any, _req: express.Request, res: express.Response, _next: express.NextFunction) => {\n  console.error(err);\n  res.status(500).json({ error: "Erreur interne du serveur." });\n});\n\nconst port = Number(process.env.PORT || 4000);\n\ninitPush();\nscheduleReminders();\n\napp.listen(port, () => {\n  console.log(`API demarree sur http://localhost:${port}`);\n});\n'
FILES['backend/src/routes/reactions.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { REACTION_CATALOG, REACTION_KEYS } from "../utils/reactions";\nimport { notifyUser } from "../services/notifications";\n\nconst router = Router();\nrouter.use(requireAuth);\n\nrouter.get("/catalog", (_req, res) => {\n  res.json(REACTION_CATALOG);\n});\n\nconst toggleSchema = z.object({\n  targetType: z.enum(["exercise", "circuit"]),\n  targetId: z.string(),\n  type: z.enum(REACTION_KEYS as [string, ...string[]]),\n});\n\n// Ajoute ou retire une reaction (bascule) sur une séance validee par un membre du même camp.\nrouter.post("/", async (req: AuthRequest, res) => {\n  const parsed = toggleSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: "Reaction invalide." });\n  }\n  const { targetType, targetId, type } = parsed.data;\n\n  // Vérifie que la cible existe et recupere son camp, pour s\'assurer que l\'utilisateur\n  // en est bien membre (on ne peut reagir qu\'aux séances de ses propres camps).\n  let campId: string | null = null;\n  let ownerId: string | null = null;\n  if (targetType === "exercise") {\n    const log = await prisma.exerciseLog.findUnique({ where: { id: targetId } });\n    campId = log?.campId ?? null;\n    ownerId = log?.userId ?? null;\n  } else {\n    const log = await prisma.campCircuitLog.findUnique({ where: { id: targetId } });\n    campId = log?.campId ?? null;\n    ownerId = log?.userId ?? null;\n  }\n  if (!campId) return res.status(404).json({ error: "Séance introuvable." });\n\n  const membership = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId } },\n  });\n  if (!membership) return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n\n  const existing = await prisma.reaction.findUnique({\n    where: { userId_targetType_targetId_type: { userId: req.userId!, targetType, targetId, type } },\n  });\n\n  if (existing) {\n    await prisma.reaction.delete({ where: { id: existing.id } });\n    return res.json({ active: false });\n  }\n\n  await prisma.reaction.create({ data: { userId: req.userId!, targetType, targetId, type } });\n\n  if (ownerId && ownerId !== req.userId) {\n    const def = REACTION_CATALOG.find((r) => r.key === type);\n    const me = await prisma.user.findUnique({ where: { id: req.userId } });\n    notifyUser(\n      ownerId,\n      "REACTION",\n      `${def?.emoji ?? "👏"} Nouvelle reaction`,\n      `${me?.name ?? "Quelqu\'un"} a reagi a ta séance (${def?.label ?? type}).`,\n      `/camps/${campId}`\n    ).catch(() => {});\n  }\n\n  res.status(201).json({ active: true });\n});\n\nexport default router;\n'
FILES['backend/src/routes/connections.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { computeOverallRegularityRate } from "../utils/badges";\nimport { notifyUser } from "../services/notifications";\n\nconst router = Router();\nrouter.use(requireAuth);\n\n// Liste mes relations : coequipiers acceptes + demandes en attente (envoyees et recues)\nrouter.get("/", async (req: AuthRequest, res) => {\n  const [sent, received] = await Promise.all([\n    prisma.connection.findMany({\n      where: { requesterId: req.userId },\n      include: { recipient: { select: { id: true, name: true, avatarBase64: true, location: true } } },\n    }),\n    prisma.connection.findMany({\n      where: { recipientId: req.userId },\n      include: { requester: { select: { id: true, name: true, avatarBase64: true, location: true } } },\n    }),\n  ]);\n\n  const accepted = [\n    ...sent.filter((c) => c.status === "ACCEPTED").map((c) => ({ connectionId: c.id, user: c.recipient })),\n    ...received.filter((c) => c.status === "ACCEPTED").map((c) => ({ connectionId: c.id, user: c.requester })),\n  ];\n  const pendingSent = sent\n    .filter((c) => c.status === "PENDING")\n    .map((c) => ({ connectionId: c.id, user: c.recipient }));\n  const pendingReceived = received\n    .filter((c) => c.status === "PENDING")\n    .map((c) => ({ connectionId: c.id, user: c.requester }));\n\n  res.json({ accepted, pendingSent, pendingReceived });\n});\n\nconst requestSchema = z.object({ recipientId: z.string() });\n\n// Envoie une demande pour devenir "coequipier" d\'un autre utilisateur\nrouter.post("/", async (req: AuthRequest, res) => {\n  const parsed = requestSchema.safeParse(req.body);\n  if (!parsed.success) return res.status(400).json({ error: "Requete invalide." });\n  const { recipientId } = parsed.data;\n\n  if (recipientId === req.userId) {\n    return res.status(400).json({ error: "Impossible de s\'ajouter soi-meme." });\n  }\n\n  const existing = await prisma.connection.findFirst({\n    where: {\n      OR: [\n        { requesterId: req.userId!, recipientId },\n        { requesterId: recipientId, recipientId: req.userId! },\n      ],\n    },\n  });\n  if (existing) {\n    return res.status(409).json({ error: "Une demande existe deja avec cette personne." });\n  }\n\n  const connection = await prisma.connection.create({\n    data: { requesterId: req.userId!, recipientId, status: "PENDING" },\n  });\n\n  const me = await prisma.user.findUnique({ where: { id: req.userId } });\n  notifyUser(\n    recipientId,\n    "TEAMMATE_REQUEST",\n    "🤝 Nouvelle demande",\n    `${me?.name ?? "Quelqu\'un"} veut devenir ton coequipier.`,\n    "/coequipiers",\n    connection.id\n  ).catch(() => {});\n\n  res.status(201).json(connection);\n});\n\n// Accepte une demande recue\nrouter.post("/:id/accept", async (req: AuthRequest, res) => {\n  const connection = await prisma.connection.findUnique({ where: { id: req.params.id } });\n  if (!connection || connection.recipientId !== req.userId) {\n    return res.status(404).json({ error: "Demande introuvable." });\n  }\n  const updated = await prisma.connection.update({ where: { id: req.params.id }, data: { status: "ACCEPTED" } });\n  res.json(updated);\n});\n\n// Refuse une demande recue, ou annule/supprime une relation existante\nrouter.delete("/:id", async (req: AuthRequest, res) => {\n  const connection = await prisma.connection.findUnique({ where: { id: req.params.id } });\n  if (!connection || (connection.recipientId !== req.userId && connection.requesterId !== req.userId)) {\n    return res.status(404).json({ error: "Relation introuvable." });\n  }\n  await prisma.connection.delete({ where: { id: req.params.id } });\n  res.status(204).send();\n});\n\nasync function areTeammatesOrCampmates(userId: string, otherUserId: string): Promise<boolean> {\n  const connection = await prisma.connection.findFirst({\n    where: {\n      status: "ACCEPTED",\n      OR: [\n        { requesterId: userId, recipientId: otherUserId },\n        { requesterId: otherUserId, recipientId: userId },\n      ],\n    },\n  });\n  if (connection) return true;\n\n  const sharedCamp = await prisma.campMembership.findFirst({\n    where: { userId: otherUserId, camp: { members: { some: { userId } } } },\n  });\n  return !!sharedCamp;\n}\n\n// Profil public d\'un coequipier (ou d\'un membre d\'un camp commun) : infos de base +\n// taux de regularite global + liste de ses camps.\nrouter.get("/:userId/profile", async (req: AuthRequest, res) => {\n  const otherUserId = req.params.userId;\n  if (!(await areTeammatesOrCampmates(req.userId!, otherUserId))) {\n    return res.status(403).json({ error: "Vous devez etre coequipiers ou partager un camp pour voir ce profil." });\n  }\n\n  const user = await prisma.user.findUnique({\n    where: { id: otherUserId },\n    select: {\n      id: true,\n      name: true,\n      avatarBase64: true,\n      location: true,\n      sport: true,\n      sportLevel: true,\n      createdAt: true,\n    },\n  });\n  if (!user) return res.status(404).json({ error: "Utilisateur introuvable." });\n\n  const [overallRegularityRate, memberships, badgeCount] = await Promise.all([\n    computeOverallRegularityRate(otherUserId),\n    prisma.campMembership.findMany({\n      where: { userId: otherUserId },\n      include: { camp: { include: { _count: { select: { members: true } } } } },\n    }),\n    prisma.userBadge.count({ where: { userId: otherUserId } }),\n  ]);\n\n  res.json({\n    ...user,\n    overallRegularityRate,\n    badgeCount,\n    camps: memberships.map((m) => ({\n      id: m.camp.id,\n      name: m.camp.name,\n      description: m.camp.description,\n      memberCount: m.camp._count.members,\n    })),\n  });\n});\n\nexport default router;\n'
FILES['backend/src/routes/campMessages.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { notifyUser } from "../services/notifications";\n\nconst router = Router();\nrouter.use(requireAuth);\n\nasync function assertMember(userId: string, campId: string) {\n  const membership = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId, campId } },\n  });\n  return !!membership;\n}\n\n// Liste les messages du camp (les plus recents en dernier), réservé aux membres du camp\nrouter.get("/:campId/messages", async (req: AuthRequest, res) => {\n  const { campId } = req.params;\n  if (!(await assertMember(req.userId!, campId))) {\n    return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n  }\n\n  const messages = await prisma.campMessage.findMany({\n    where: { campId },\n    include: { user: { select: { id: true, name: true } } },\n    orderBy: { createdAt: "asc" },\n    take: 200, // garde-fou simple : les 200 derniers messages\n  });\n\n  res.json(messages);\n});\n\nconst sendSchema = z.object({ body: z.string().min(1).max(2000) });\n\n// Envoie un message dans le camp, réservé aux membres du camp\nrouter.post("/:campId/messages", async (req: AuthRequest, res) => {\n  const { campId } = req.params;\n  if (!(await assertMember(req.userId!, campId))) {\n    return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n  }\n\n  const parsed = sendSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: "Le message ne peut pas être vide." });\n  }\n\n  const message = await prisma.campMessage.create({\n    data: { campId, userId: req.userId!, body: parsed.data.body.trim() },\n    include: { user: { select: { id: true, name: true } } },\n  });\n\n  // Notifie les autres membres du camp (pas l\'expediteur), sans bloquer la réponse\n  prisma.camp.findUnique({ where: { id: campId } }).then((camp) => {\n    prisma.campMembership\n      .findMany({ where: { campId, userId: { not: req.userId } } })\n      .then((others) => {\n        const preview = message.body.length > 80 ? `${message.body.slice(0, 80)}…` : message.body;\n        for (const m of others) {\n          notifyUser(\n            m.userId,\n            "CAMP_MESSAGE",\n            `💬 ${camp?.name ?? "Camp"}`,\n            `${message.user.name} : ${preview}`,\n            `/camps/${campId}/discussion`\n          ).catch(() => {});\n        }\n      });\n  });\n\n  res.status(201).json(message);\n});\n\nexport default router;\n'
FILES['backend/src/routes/messages.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { notifyUser } from "../services/notifications";\n\nconst router = Router();\nrouter.use(requireAuth);\n\n// Renvoie la liste des personnes avec qui on peut discuter : celles qui partagent\n// au moins un camp avec l\'utilisateur (on ne permet pas d\'ecrire a un inconnu).\nrouter.get("/contacts", async (req: AuthRequest, res) => {\n  const myMemberships = await prisma.campMembership.findMany({\n    where: { userId: req.userId },\n    select: { campId: true },\n  });\n  const campIds = myMemberships.map((m) => m.campId);\n\n  if (campIds.length === 0) return res.json([]);\n\n  const otherMemberships = await prisma.campMembership.findMany({\n    where: { campId: { in: campIds }, userId: { not: req.userId } },\n    include: { user: { select: { id: true, name: true } } },\n  });\n\n  const contactsById = new Map(otherMemberships.map((m) => [m.user.id, m.user]));\n  res.json([...contactsById.values()]);\n});\n\nasync function assertContact(userId: string, otherUserId: string): Promise<boolean> {\n  const shared = await prisma.campMembership.findFirst({\n    where: {\n      userId: otherUserId,\n      camp: { members: { some: { userId } } },\n    },\n  });\n  return !!shared;\n}\n\n// Recupere la conversation avec un utilisateur donne (dans les deux sens)\nrouter.get("/:userId", async (req: AuthRequest, res) => {\n  const otherUserId = req.params.userId;\n  if (!(await assertContact(req.userId!, otherUserId))) {\n    return res.status(403).json({ error: "Vous ne partagez aucun camp ensemble." });\n  }\n\n  const messages = await prisma.directMessage.findMany({\n    where: {\n      OR: [\n        { senderId: req.userId, recipientId: otherUserId },\n        { senderId: otherUserId, recipientId: req.userId },\n      ],\n    },\n    orderBy: { createdAt: "asc" },\n    take: 300,\n  });\n\n  res.json(messages);\n});\n\nconst sendSchema = z.object({ recipientId: z.string(), body: z.string().min(1).max(2000) });\n\n// Envoie un message prive, uniquement possible si les deux utilisateurs partagent un camp\nrouter.post("/", async (req: AuthRequest, res) => {\n  const parsed = sendSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: "Message invalide." });\n  }\n  const { recipientId, body } = parsed.data;\n\n  if (recipientId === req.userId) {\n    return res.status(400).json({ error: "Impossible de s\'envoyer un message a soi-même." });\n  }\n  if (!(await assertContact(req.userId!, recipientId))) {\n    return res.status(403).json({ error: "Vous ne partagez aucun camp ensemble." });\n  }\n\n  const message = await prisma.directMessage.create({\n    data: { senderId: req.userId!, recipientId, body: body.trim() },\n  });\n\n  const sender = await prisma.user.findUnique({ where: { id: req.userId } });\n  const preview = body.trim().length > 80 ? `${body.trim().slice(0, 80)}…` : body.trim();\n  notifyUser(recipientId, "DIRECT_MESSAGE", `💬 Message de ${sender?.name ?? ""}`, preview, "/messages").catch(() => {});\n\n  res.status(201).json(message);\n});\n\nexport default router;\n'
FILES['backend/src/routes/campExercises.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { notifyUser } from "../services/notifications";\n\nconst router = Router();\nrouter.use(requireAuth);\n\nconst recurrenceSchema = z.discriminatedUnion("recurrenceType", [\n  z.object({ recurrenceType: z.literal("DAILY") }),\n  z.object({ recurrenceType: z.literal("WEEKLY"), daysOfWeek: z.array(z.number().min(0).max(6)).min(1) }),\n  z.object({ recurrenceType: z.literal("EVERY_N_DAYS"), intervalDays: z.number().min(1) }),\n  z.object({ recurrenceType: z.literal("WEEKLY_COUNT"), timesPerWeek: z.number().min(1).max(7) }),\n]);\n\nconst targetSchema = z.discriminatedUnion("targetMode", [\n  z.object({ targetMode: z.literal("FIXED"), targetValue: z.number().min(1) }),\n  z.object({ targetMode: z.literal("MAX"), targetValue: z.number().min(1).optional() }),\n]);\n\nconst updateSchema = z\n  .object({\n    campId: z.string(),\n    exerciseId: z.string(),\n    description: z.string().max(500).optional().nullable(),\n    targetSets: z.number().min(1),\n  })\n  .and(targetSchema)\n  .and(recurrenceSchema);\n\n// Met à jour la consigne d\'un exercice au sein d\'un camp : réservé au créateur du camp\n// (la "casquette entraîneur"). Les autres membres ne peuvent que consulter.\nrouter.put("/", async (req: AuthRequest, res) => {\n  const parsed = updateSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n  const data = parsed.data;\n\n  const camp = await prisma.camp.findUnique({ where: { id: data.campId } });\n  if (!camp) return res.status(404).json({ error: "Camp introuvable." });\n  if (camp.createdById !== req.userId) {\n    return res.status(403).json({ error: "Seul le créateur du camp peut définir les consignes des exercices." });\n  }\n\n  const campExercise = await prisma.campExercise.findUnique({\n    where: { campId_exerciseId: { campId: data.campId, exerciseId: data.exerciseId } },\n  });\n  if (!campExercise) return res.status(400).json({ error: "Cet exercice ne fait pas partie du camp." });\n\n  const updated = await prisma.campExercise.update({\n    where: { campId_exerciseId: { campId: data.campId, exerciseId: data.exerciseId } },\n    data: {\n      description: data.description ?? null,\n      targetSets: data.targetSets,\n      targetMode: data.targetMode,\n      targetValue: data.targetMode === "FIXED" ? data.targetValue : data.targetValue ?? null,\n      recurrenceType: data.recurrenceType,\n      daysOfWeek: data.recurrenceType === "WEEKLY" ? JSON.stringify(data.daysOfWeek) : null,\n      intervalDays: data.recurrenceType === "EVERY_N_DAYS" ? data.intervalDays : null,\n      timesPerWeek: data.recurrenceType === "WEEKLY_COUNT" ? data.timesPerWeek : null,\n    },\n    include: { exercise: true },\n  });\n\n  prisma.campMembership.findMany({ where: { campId: data.campId, userId: { not: req.userId } } }).then((others) => {\n    for (const m of others) {\n      notifyUser(\n        m.userId,\n        "CAMP_UPDATED",\n        `📋 ${camp.name}`,\n        `La consigne de "${updated.exercise.name}" a ete modifiee.`,\n        `/camps/${data.campId}`\n      ).catch(() => {});\n    }\n  });\n\n  res.json(updated);\n});\n\nexport default router;\n'
FILES['backend/src/routes/campCircuits.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { toDayStart } from "../utils/recurrence";\nimport { checkAndAwardBadges } from "../utils/badges";\nimport { notifyUser } from "../services/notifications";\n\nconst router = Router();\nrouter.use(requireAuth);\n\nconst recurrenceSchema = z.discriminatedUnion("recurrenceType", [\n  z.object({ recurrenceType: z.literal("DAILY") }),\n  z.object({ recurrenceType: z.literal("WEEKLY"), daysOfWeek: z.array(z.number().min(0).max(6)).min(1) }),\n  z.object({ recurrenceType: z.literal("EVERY_N_DAYS"), intervalDays: z.number().min(1) }),\n  z.object({ recurrenceType: z.literal("WEEKLY_COUNT"), timesPerWeek: z.number().min(1).max(7) }),\n]);\n\nconst circuitSchema = z\n  .object({\n    campId: z.string(),\n    name: z.string().min(1, "Le nom du circuit est requis."),\n    description: z.string().max(500).optional().nullable(),\n    items: z.array(z.object({ exerciseId: z.string().optional(), name: z.string().min(1) })).min(1, "Ajoute au moins un exercice au circuit."),\n    workSeconds: z.number().min(5),\n    restSeconds: z.number().min(0),\n    rounds: z.number().min(1),\n    roundRestSeconds: z.number().min(0),\n  })\n  .and(recurrenceSchema);\n\nasync function assertCoach(userId: string, campId: string) {\n  const camp = await prisma.camp.findUnique({ where: { id: campId } });\n  if (!camp) return { ok: false as const, status: 404, error: "Camp introuvable." };\n  if (camp.createdById !== userId) {\n    return { ok: false as const, status: 403, error: "Seul le créateur du camp peut définir les circuits." };\n  }\n  return { ok: true as const, campName: camp.name };\n}\n\nasync function notifyOtherMembers(campId: string, exceptUserId: string, campName: string, message: string) {\n  const others = await prisma.campMembership.findMany({ where: { campId, userId: { not: exceptUserId } } });\n  for (const m of others) {\n    notifyUser(m.userId, "CAMP_UPDATED", `📋 ${campName}`, message, `/camps/${campId}`).catch(() => {});\n  }\n}\n\n// Créé un circuit training pour un camp : réservé au créateur du camp\nrouter.post("/", async (req: AuthRequest, res) => {\n  const parsed = circuitSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n  const data = parsed.data;\n\n  const check = await assertCoach(req.userId!, data.campId);\n  if (!check.ok) return res.status(check.status).json({ error: check.error });\n\n  const circuit = await prisma.campCircuit.create({\n    data: {\n      campId: data.campId,\n      name: data.name,\n      description: data.description ?? null,\n      items: JSON.stringify(data.items),\n      workSeconds: data.workSeconds,\n      restSeconds: data.restSeconds,\n      rounds: data.rounds,\n      roundRestSeconds: data.roundRestSeconds,\n      recurrenceType: data.recurrenceType,\n      daysOfWeek: data.recurrenceType === "WEEKLY" ? JSON.stringify(data.daysOfWeek) : null,\n      intervalDays: data.recurrenceType === "EVERY_N_DAYS" ? data.intervalDays : null,\n      timesPerWeek: data.recurrenceType === "WEEKLY_COUNT" ? data.timesPerWeek : null,\n    },\n  });\n\n  notifyOtherMembers(data.campId, req.userId!, check.campName, `Nouveau circuit "${circuit.name}" ajoute.`);\n\n  res.status(201).json(circuit);\n});\n\n// Modifie un circuit existant : réservé au créateur du camp\nrouter.put("/:id", async (req: AuthRequest, res) => {\n  const existing = await prisma.campCircuit.findUnique({ where: { id: req.params.id } });\n  if (!existing) return res.status(404).json({ error: "Circuit introuvable." });\n\n  const parsed = circuitSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n  const data = parsed.data;\n\n  const check = await assertCoach(req.userId!, data.campId);\n  if (!check.ok) return res.status(check.status).json({ error: check.error });\n\n  const circuit = await prisma.campCircuit.update({\n    where: { id: req.params.id },\n    data: {\n      name: data.name,\n      description: data.description ?? null,\n      items: JSON.stringify(data.items),\n      workSeconds: data.workSeconds,\n      restSeconds: data.restSeconds,\n      rounds: data.rounds,\n      roundRestSeconds: data.roundRestSeconds,\n      recurrenceType: data.recurrenceType,\n      daysOfWeek: data.recurrenceType === "WEEKLY" ? JSON.stringify(data.daysOfWeek) : null,\n      intervalDays: data.recurrenceType === "EVERY_N_DAYS" ? data.intervalDays : null,\n      timesPerWeek: data.recurrenceType === "WEEKLY_COUNT" ? data.timesPerWeek : null,\n    },\n  });\n\n  notifyOtherMembers(data.campId, req.userId!, check.campName, `Le circuit "${circuit.name}" a ete modifie.`);\n\n  res.json(circuit);\n});\n\n// Supprime un circuit : réservé au créateur du camp\nrouter.delete("/:id", async (req: AuthRequest, res) => {\n  const existing = await prisma.campCircuit.findUnique({ where: { id: req.params.id } });\n  if (!existing) return res.status(404).json({ error: "Circuit introuvable." });\n\n  const check = await assertCoach(req.userId!, existing.campId);\n  if (!check.ok) return res.status(check.status).json({ error: check.error });\n\n  await prisma.campCircuit.delete({ where: { id: req.params.id } });\n  res.status(204).send();\n});\n\nconst logSchema = z.object({ durationSeconds: z.number().min(0) });\n\n// Valide la réalisation d\'un circuit de camp pour aujourd\'hui (accessible à tout membre du camp)\nrouter.post("/:id/log", async (req: AuthRequest, res) => {\n  const circuit = await prisma.campCircuit.findUnique({ where: { id: req.params.id } });\n  if (!circuit) return res.status(404).json({ error: "Circuit introuvable." });\n\n  const membership = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId: circuit.campId } },\n  });\n  if (!membership) return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n\n  const parsed = logSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: "Durée invalide." });\n  }\n\n  const day = toDayStart(new Date());\n  const log = await prisma.campCircuitLog.upsert({\n    where: { userId_campCircuitId_date: { userId: req.userId!, campCircuitId: circuit.id, date: day } },\n    create: {\n      userId: req.userId!,\n      campCircuitId: circuit.id,\n      campId: circuit.campId,\n      date: day,\n      durationSeconds: parsed.data.durationSeconds,\n      completed: true,\n    },\n    update: { durationSeconds: parsed.data.durationSeconds, completed: true },\n  });\n\n  const newBadges = await checkAndAwardBadges(req.userId!);\n  res.status(201).json({ log, newBadges });\n});\n\nexport default router;\n'
FILES['frontend/src/components/ReactionPicker.tsx'] = 'import { useState } from "react";\nimport { api } from "../api/client";\n\nconst REACTIONS = [\n  { key: "OVATION", label: "Ovation", emoji: "🙌" },\n  { key: "RESPECT", label: "Respect", emoji: "🫡" },\n  { key: "HAKA", label: "Haka", emoji: "💥" },\n  { key: "OLA", label: "Ola", emoji: "🌊" },\n  { key: "HYMNE", label: "Hymne", emoji: "🎶" },\n  { key: "CLAPPING", label: "Clapping", emoji: "👏" },\n  { key: "TIFO", label: "Tifo", emoji: "🎨" },\n  { key: "TAMBOURINAGE", label: "Tambourinage", emoji: "🥁" },\n];\n\nexport interface ReactionSummary {\n  type: string;\n  count: number;\n  reactedByMe: boolean;\n}\n\ninterface Props {\n  targetType: "exercise" | "circuit";\n  targetId: string;\n  reactions: ReactionSummary[];\n  onChange: () => void;\n}\n\nexport default function ReactionPicker({ targetType, targetId, reactions, onChange }: Props) {\n  const [open, setOpen] = useState(false);\n\n  async function toggle(type: string) {\n    setOpen(false);\n    await api.post("/reactions", { targetType, targetId, type });\n    onChange();\n  }\n\n  return (\n    <div className="relative inline-block">\n      <div className="flex items-center gap-1 flex-wrap">\n        {reactions.map((r) => {\n          const def = REACTIONS.find((d) => d.key === r.type);\n          if (!def) return null;\n          return (\n            <button\n              key={r.type}\n              onClick={() => toggle(r.type)}\n              title={def.label}\n              className={`text-xs rounded-full px-2 py-0.5 border ${\n                r.reactedByMe ? "bg-accent/20 border-accent" : "bg-surface2 border-border"\n              }`}\n            >\n              {def.emoji} {r.count}\n            </button>\n          );\n        })}\n        <button\n          onClick={() => setOpen((o) => !o)}\n          className="text-xs rounded-full px-2 py-0.5 border border-dashed border-border text-muted hover:text-accent"\n        >\n          + reagir\n        </button>\n      </div>\n\n      {open && (\n        <div className="absolute z-10 right-0 mt-1 bg-surface border border-border rounded-lg p-2 grid grid-cols-4 gap-1 shadow-lg w-max max-w-[85vw]">\n          {REACTIONS.map((r) => (\n            <button\n              key={r.key}\n              onClick={() => toggle(r.key)}\n              title={r.label}\n              className="text-xl hover:bg-surface2 rounded p-1"\n            >\n              {r.emoji}\n            </button>\n          ))}\n        </div>\n      )}\n    </div>\n  );\n}\n'
FILES['frontend/src/index.css'] = '@tailwind base;\n@tailwind components;\n@tailwind utilities;\n\n:root {\n  color-scheme: light;\n}\n\nhtml,\nbody,\n#root {\n  height: 100%;\n  max-width: 100%;\n  overflow-x: hidden;\n}\n\nbody {\n  background-color: #f2fafb;\n  background-image:\n    radial-gradient(circle at 8% -5%, rgba(14, 160, 176, 0.10), transparent 42%),\n    radial-gradient(circle at 95% 105%, rgba(76, 175, 80, 0.08), transparent 48%);\n  color: #152b31;\n  font-family: "Inter", sans-serif;\n}\n\nh1,\nh2,\nh3,\n.font-display {\n  font-family: "Baloo 2", sans-serif;\n  letter-spacing: 0.01em;\n  font-weight: 700;\n}\n\n/* Degrade signature de la marque (bleu vers vert, repris du logo), pour les elements\n   les plus visibles (logo, ecrans de connexion, gros boutons d\'action). */\n.brand-gradient {\n  background-image: linear-gradient(120deg, #0EA0B0 0%, #4CAF50 100%);\n}\n.brand-gradient-text {\n  background-image: linear-gradient(120deg, #0EA0B0 0%, #4CAF50 100%);\n  -webkit-background-clip: text;\n  background-clip: text;\n  color: transparent;\n}\n\n/* Focus visible clair pour l\'accessibilite clavier */\na:focus-visible,\nbutton:focus-visible,\ninput:focus-visible,\nselect:focus-visible,\ntextarea:focus-visible {\n  outline: 2px solid #0ea0b0;\n  outline-offset: 2px;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  * {\n    animation-duration: 0.001ms !important;\n    transition-duration: 0.001ms !important;\n  }\n}\n\n/* --- Tampon de validation (signature visuelle de l\'app) --- */\n.stamp-cell {\n  position: relative;\n  border-radius: 5px;\n  transition: transform 120ms ease, background-color 150ms ease;\n}\n.stamp-cell.done {\n  background-color: rgba(76, 175, 80, 0.18);\n  border: 1px solid rgba(76, 175, 80, 0.55);\n}\n/* "manque" reste neutre (gris-ambre) plutot que rouge : on encourage, on ne sanctionne pas */\n.stamp-cell.missed {\n  background-color: rgba(201, 162, 39, 0.12);\n  border: 1px solid rgba(201, 162, 39, 0.35);\n}\n.stamp-cell.future {\n  background-color: transparent;\n  border: 1px dashed #d5e6ea;\n}\n\n.stamp-btn {\n  transition: transform 100ms ease, box-shadow 150ms ease;\n}\n.stamp-btn:active {\n  transform: scale(0.94) rotate(-2deg);\n}\n\n/* Petit rebond satisfaisant quand une seance vient d\'etre validee */\n@keyframes pop-success {\n  0% { transform: scale(0.8); opacity: 0.5; }\n  60% { transform: scale(1.12); }\n  100% { transform: scale(1); opacity: 1; }\n}\n.pop-success {\n  animation: pop-success 320ms ease-out;\n}\n'
FILES['frontend/src/components/NotificationBell.tsx'] = 'import { useEffect, useRef, useState } from "react";\nimport { useNavigate } from "react-router-dom";\nimport { api } from "../api/client";\n\ninterface NotificationItem {\n  id: string;\n  type: string;\n  title: string;\n  body: string;\n  link: string | null;\n  relatedId: string | null;\n  read: boolean;\n  createdAt: string;\n}\n\nfunction timeAgo(dateStr: string): string {\n  const diffMs = Date.now() - new Date(dateStr).getTime();\n  const mins = Math.floor(diffMs / 60000);\n  if (mins < 1) return "a l\'instant";\n  if (mins < 60) return `il y a ${mins} min`;\n  const hours = Math.floor(mins / 60);\n  if (hours < 24) return `il y a ${hours} h`;\n  const days = Math.floor(hours / 24);\n  return `il y a ${days} j`;\n}\n\nexport default function NotificationBell() {\n  const navigate = useNavigate();\n  const [open, setOpen] = useState(false);\n  const [unreadCount, setUnreadCount] = useState(0);\n  const [notifications, setNotifications] = useState<NotificationItem[] | null>(null);\n  const panelRef = useRef<HTMLDivElement>(null);\n\n  function loadUnreadCount() {\n    api.get<{ count: number }>("/notifications/unread-count").then((res) => setUnreadCount(res.count));\n  }\n\n  useEffect(() => {\n    loadUnreadCount();\n    const interval = setInterval(loadUnreadCount, 20000);\n    return () => clearInterval(interval);\n  }, []);\n\n  useEffect(() => {\n    function onClickOutside(e: MouseEvent) {\n      if (panelRef.current && !panelRef.current.contains(e.target as Node)) setOpen(false);\n    }\n    if (open) document.addEventListener("mousedown", onClickOutside);\n    return () => document.removeEventListener("mousedown", onClickOutside);\n  }, [open]);\n\n  async function toggleOpen() {\n    const willOpen = !open;\n    setOpen(willOpen);\n    if (willOpen) {\n      const list = await api.get<NotificationItem[]>("/notifications");\n      setNotifications(list);\n    }\n  }\n\n  async function onItemClick(n: NotificationItem) {\n    if (!n.read) {\n      await api.post(`/notifications/${n.id}/read`, {});\n      setUnreadCount((c) => Math.max(0, c - 1));\n      setNotifications((prev) => prev?.map((x) => (x.id === n.id ? { ...x, read: true } : x)) ?? null);\n    }\n    setOpen(false);\n    if (n.link) navigate(n.link);\n  }\n\n  async function markAllRead() {\n    await api.post("/notifications/read-all", {});\n    setUnreadCount(0);\n    setNotifications((prev) => prev?.map((x) => ({ ...x, read: true })) ?? null);\n  }\n\n  async function respondToTeammateRequest(n: NotificationItem, accept: boolean) {\n    if (!n.relatedId) return;\n    if (accept) {\n      await api.post(`/connections/${n.relatedId}/accept`, {});\n    } else {\n      await api.del(`/connections/${n.relatedId}`);\n    }\n    await api.post(`/notifications/${n.id}/read`, {});\n    setNotifications((prev) => prev?.map((x) => (x.id === n.id ? { ...x, read: true } : x)) ?? null);\n    setUnreadCount((c) => Math.max(0, c - (n.read ? 0 : 1)));\n  }\n\n  const typeEmoji: Record<string, string> = {\n    REACTION: "👏",\n    CAMP_MESSAGE: "💬",\n    DIRECT_MESSAGE: "💬",\n    TEAMMATE_REQUEST: "🤝",\n    CAMP_UPDATED: "📋",\n    REMINDER: "💪",\n  };\n\n  return (\n    <div className="relative" ref={panelRef}>\n      <button\n        onClick={toggleOpen}\n        className="relative w-9 h-9 rounded-full flex items-center justify-center hover:bg-surface2 transition-colors"\n        aria-label="Notifications"\n      >\n        <span className="text-lg">🔔</span>\n        {unreadCount > 0 && (\n          <span className="absolute -top-0.5 -right-0.5 bg-accent text-white text-[10px] font-semibold rounded-full min-w-[16px] h-4 px-1 flex items-center justify-center">\n            {unreadCount > 9 ? "9+" : unreadCount}\n          </span>\n        )}\n      </button>\n\n      {open && (\n        <div className="absolute right-0 mt-2 w-80 max-w-[90vw] max-h-[70vh] overflow-y-auto bg-surface border border-border rounded-xl shadow-lg z-50">\n          <div className="flex items-center justify-between p-3 border-b border-border sticky top-0 bg-surface">\n            <p className="font-display uppercase tracking-wide text-sm">Notifications</p>\n            {unreadCount > 0 && (\n              <button onClick={markAllRead} className="text-xs text-accent hover:text-accentSoft">\n                Tout marquer lu\n              </button>\n            )}\n          </div>\n\n          {notifications === null && <p className="text-muted text-sm p-4">Chargement...</p>}\n          {notifications?.length === 0 && (\n            <p className="text-muted text-sm p-4 text-center">Rien de nouveau pour l\'instant.</p>\n          )}\n\n          <div className="divide-y divide-border">\n            {notifications?.map((n) => (\n              <div key={n.id} className={`p-3 ${n.read ? "" : "bg-accent/5"}`}>\n                <button onClick={() => onItemClick(n)} className="w-full text-left">\n                  <div className="flex items-start gap-2">\n                    <span className="text-lg shrink-0">{typeEmoji[n.type] ?? "🔔"}</span>\n                    <div className="flex-1 min-w-0">\n                      <p className="text-sm font-medium">{n.title}</p>\n                      <p className="text-xs text-muted">{n.body}</p>\n                      <p className="text-[10px] text-muted mt-0.5">{timeAgo(n.createdAt)}</p>\n                    </div>\n                    {!n.read && <span className="w-2 h-2 rounded-full bg-accent shrink-0 mt-1" />}\n                  </div>\n                </button>\n                {n.type === "TEAMMATE_REQUEST" && !n.read && (\n                  <div className="flex gap-2 mt-2 ml-7">\n                    <button\n                      onClick={() => respondToTeammateRequest(n, true)}\n                      className="text-xs bg-accent text-white font-semibold rounded-md px-3 py-1"\n                    >\n                      Accepter\n                    </button>\n                    <button\n                      onClick={() => respondToTeammateRequest(n, false)}\n                      className="text-xs text-muted hover:text-accent"\n                    >\n                      Refuser\n                    </button>\n                  </div>\n                )}\n              </div>\n            ))}\n          </div>\n        </div>\n      )}\n    </div>\n  );\n}\n'
FILES['frontend/src/components/Layout.tsx'] = 'import { NavLink, useNavigate } from "react-router-dom";\nimport { ReactNode } from "react";\nimport { useAuth } from "../context/AuthContext";\nimport NotificationBell from "./NotificationBell";\n\nconst desktopNavItems = [\n  { to: "/aujourdhui", label: "Aujourd\'hui" },\n  { to: "/camps", label: "Mes camps" },\n  { to: "/chrono", label: "Chrono" },\n  { to: "/exercices", label: "Exercices" },\n  { to: "/messages", label: "Messages" },\n  { to: "/coequipiers", label: "Coequipiers" },\n  { to: "/historique", label: "Historique" },\n  { to: "/profil", label: "Profil" },\n];\n\n// Sur mobile, la barre du bas ne montre que l\'essentiel : le Chrono a sa propre bulle\n// centrale, les autres onglets (Exercices, Historique) restent accessibles depuis le menu\n// complet sur ordinateur, ou via des liens dans "Mes camps" / "Profil" sur mobile.\nconst mobileLeftItems = [\n  { to: "/aujourdhui", label: "Aujourd\'hui", icon: "📅" },\n  { to: "/camps", label: "Camps", icon: "🏕️" },\n];\nconst mobileRightItems = [\n  { to: "/messages", label: "Messages", icon: "💬" },\n  { to: "/profil", label: "Profil", icon: "👤" },\n];\n\nexport default function Layout({ children }: { children: ReactNode }) {\n  const { user, logout } = useAuth();\n  const navigate = useNavigate();\n\n  return (\n    <div className="min-h-screen flex flex-col md:flex-row">\n      <header className="md:w-64 md:min-h-screen border-b md:border-b-0 md:border-r border-border bg-surface flex md:flex-col justify-between">\n        <div className="p-4 md:p-6 w-full">\n          <div className="flex items-center justify-between md:justify-start gap-2 mb-0 md:mb-8">\n            <div className="w-9 md:hidden" />\n            <div className="flex items-center gap-2">\n              <img src="/logo-mark.png" alt="" className="w-11 h-11 md:w-8 md:h-8 object-contain" />\n              <span className="font-display text-xl md:text-lg tracking-wide uppercase">GoTeam</span>\n            </div>\n            <div className="md:hidden">\n              <NotificationBell />\n            </div>\n            <div className="hidden md:block md:ml-auto">\n              <NotificationBell />\n            </div>\n          </div>\n          <nav className="hidden md:flex md:flex-col gap-1">\n            {desktopNavItems.map((item) => (\n              <NavLink\n                key={item.to}\n                to={item.to}\n                className={({ isActive }) =>\n                  `px-3 py-2 rounded-md text-sm font-medium transition-colors ${\n                    isActive ? "bg-accent/15 text-accent" : "text-muted hover:text-text hover:bg-surface2"\n                  }`\n                }\n              >\n                {item.label}\n              </NavLink>\n            ))}\n          </nav>\n        </div>\n        <div className="p-6 hidden md:block">\n          {user && <p className="text-xs text-muted mb-2 truncate">{user.name}</p>}\n          <button\n            onClick={() => {\n              logout();\n              navigate("/connexion");\n            }}\n            className="text-sm text-muted hover:text-accent transition-colors"\n          >\n            Se déconnecter\n          </button>\n        </div>\n      </header>\n\n      <main className="flex-1 p-5 pb-24 md:p-10 md:pb-10 max-w-4xl mx-auto w-full order-1">{children}</main>\n\n      {/* Barre de navigation mobile, fixee en bas, avec le Chrono en bulle centrale */}\n      <nav className="md:hidden fixed bottom-0 inset-x-0 bg-surface border-t border-border flex items-end justify-around pb-1 pt-2 z-40">\n        {mobileLeftItems.map((item) => (\n          <NavLink\n            key={item.to}\n            to={item.to}\n            className={({ isActive }) =>\n              `flex-1 flex flex-col items-center gap-0.5 py-1 text-[10px] font-medium ${\n                isActive ? "text-accent" : "text-muted"\n              }`\n            }\n          >\n            <span className="text-lg leading-none">{item.icon}</span>\n            {item.label}\n          </NavLink>\n        ))}\n\n        <NavLink to="/chrono" className="flex-1 flex flex-col items-center -mt-7">\n          {({ isActive }) => (\n            <>\n              <span\n                className={`w-14 h-14 rounded-full flex items-center justify-center text-2xl shadow-lg border-4 border-bg ${\n                  isActive ? "bg-accentSoft" : "bg-accent"\n                } text-bg`}\n              >\n                ⏱\n              </span>\n              <span className={`text-[10px] font-medium mt-0.5 ${isActive ? "text-accent" : "text-muted"}`}>\n                Chrono\n              </span>\n            </>\n          )}\n        </NavLink>\n\n        {mobileRightItems.map((item) => (\n          <NavLink\n            key={item.to}\n            to={item.to}\n            className={({ isActive }) =>\n              `flex-1 flex flex-col items-center gap-0.5 py-1 text-[10px] font-medium ${\n                isActive ? "text-accent" : "text-muted"\n              }`\n            }\n          >\n            <span className="text-lg leading-none">{item.icon}</span>\n            {item.label}\n          </NavLink>\n        ))}\n      </nav>\n    </div>\n  );\n}\n'

for rel_path, content in FILES.items():
    p = pathlib.Path(rel_path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(content, encoding='utf-8')
    print('OK ->', rel_path)

print()
